**Describe the bug**

The `simplify` method in Solver consumes resources, which can interfere with the `rlimit-per` option.

Here's an example:
```
#include <iostream>
#include <cvc5/cvc5.h>

using namespace cvc5;

int main() {
  Solver solver;
  solver.setOption("rlimit-per", "30");

  std::cout << "Using version " << solver.getInfo("version") << std::endl;
  
  // this loop exhausts the resource limit
  for (unsigned i = 0; i<20; i++) {
    Term t = solver.mkBitVector(64, i << 3);
    Op select = solver.mkOp(BITVECTOR_EXTRACT, { 3 * i, 2 * i });
    Term u = solver.mkTerm(select, { t });
    Term v = solver.simplify(u);
    std::cout << "Term: " << u << " simplifies to "<< v << std::endl;
  }

  // all subsequent calls to checkSat fail with ResourceOut
  Term test = solver.mkTrue();
  solver.assertFormula(test);
  Result result = solver.checkSat();
  std::cout << "Result: " << result << std::endl;

  solver.resetAssertions();
  solver.assertFormula(test);
  result = solver.checkSat();
  std::cout << "Result: " << result << std::endl;

  return 0;
}
```

When running this, the two calls to `checkSat()` produce unknown/ResourceOut. Without the calls to `simplify`
the code prints `sat` as expected.

I'm using 2e08fc09709c11c736742a07a9811a637049b649.

**Describe the bug**
Received a SIGSEGV when trying to simplify a term of an array sort
with both index and value being the same nested recursive datatype.

Conceptual reproduction
- Define a nested recursive data type
  ```rust
  datatype A {
    v1,
    v2,
    v3 (array [A -> A]
  }
  ```
- Create two new terms:
  ```rust
  term_v1 = A::v1();
  term_v2 = A::v2();
  ```
- Create a constant array:
  ```rust
  term_array = const array [A -> A] with default term_v1
  ```
- Update this array with a `Store` operation
   ```rust
   term_updated = store(term_array, term_v2, term_v2);
   ```
- Simplify the new term `term_updated` --> **This will trigger a `SIGSEGV`**

Here is a test case in C++ for the problem

```cpp
#include <cvc5/cvc5.h>

int main() {
  cvc5::Solver solver;

  // allow recursive datatype
  solver.setOption("dt-cyclic", "true");
  solver.setOption("dt-nested-rec", "true");

  // the recursive datatype declaration:
  // datatype A {
  //   v1,
  //   v2,
  //   v3 { value: array[A -> A] },
  // }
  auto sort_placeholder = solver.mkUnresolvedDatatypeSort("A", 0);
  auto decl = solver.mkDatatypeDecl("A");
  auto v1 = solver.mkDatatypeConstructorDecl("v1");
  decl.addConstructor(v1);
  auto v2 = solver.mkDatatypeConstructorDecl("v2");
  decl.addConstructor(v2);
#ifndef IGNORE_NESTED
  auto v3 = solver.mkDatatypeConstructorDecl("v3");
  v3.addSelector("value",
                 solver.mkArraySort(sort_placeholder, sort_placeholder));
  decl.addConstructor(v3);
#endif
  auto sort_a = solver.mkDatatypeSort(decl);

  // create two dummy terms, both of sort A, with v1 and v2 variants
  auto v1_ctor = sort_a.getDatatype().getConstructor("v1").getTerm();
  auto term_v1 = solver.mkTerm(cvc5::APPLY_CONSTRUCTOR, {v1_ctor});
  auto v2_ctor = sort_a.getDatatype().getConstructor("v2").getTerm();
  auto term_v2 = solver.mkTerm(cvc5::APPLY_CONSTRUCTOR, {v2_ctor});

  // create the array term: (constant array)
  auto sort_array_of_a_to_a = solver.mkArraySort(sort_a, sort_a);
  auto term_array = solver.mkConstArray(sort_array_of_a_to_a, term_v1);

  // update the array with a store
  auto term_a_array_updated =
      solver.mkTerm(cvc5::STORE, {term_array, term_v2, term_v2});

  // SIMPLIFICATION TRIGGERS A PANIC HERE!
  solver.simplify(term_a_array_updated);
}
```

