Sygus solver can accept formulas with declared constants in another solver. 
The example below demonstrates this issue with the line
```cpp
sygusSolver.addSygusConstraint(formula);
```
and sygus returns `(NO_SOLUTION)` in this case. 
This issue is captured at the parser level, but can sygus solver capture it at the API level? 

```cpp
#include <cvc5/cvc5.h>

#include <iostream>
#include <numeric>

using namespace cvc5;

/**
 * Get the string version of define-fun command.
 * @param f the function to print
 * @param params the function parameters
 * @param body the function body
 * @return a string version of define-fun
 */
std::string defineFunToString(const cvc5::Term& f,
                              const std::vector<cvc5::Term>& params,
                              const cvc5::Term& body)
{
  cvc5::Sort sort = f.getSort();
  if (sort.isFunction())
  {
    sort = sort.getFunctionCodomainSort();
  }
  std::stringstream ss;
  ss << "(define-fun " << f << " (";
  for (size_t i = 0, n = params.size(); i < n; ++i)
  {
    if (i > 0)
    {
      ss << ' ';
    }
    ss << '(' << params[i] << ' ' << params[i].getSort() << ')';
  }
  ss << ") " << sort << ' ' << body << ')';
  return ss.str();
}

void printSynthSolutions(const std::vector<cvc5::Term>& terms,
                         const std::vector<cvc5::Term>& sols)
{
  std::cout << '(' << std::endl;
  for (size_t i = 0, n = terms.size(); i < n; ++i)
  {
    std::vector<cvc5::Term> params;
    cvc5::Term body = sols[i];
    if (sols[i].getKind() == cvc5::LAMBDA)
    {
      params.insert(params.end(), sols[i][0].begin(), sols[i][0].end());
      body = sols[i][1];
    }
    std::cout << "  " << defineFunToString(terms[i], params, body) << std::endl;
  }
  std::cout << ')' << std::endl;
}

int main()
{
  Solver smtSolver;
  smtSolver.setOption("produce-models", "true");
  smtSolver.setOption("sygus", "true");
  smtSolver.setOption("incremental", "false");

  smtSolver.setLogic("LIA");
  Sort intSort = smtSolver.getIntegerSort();

  Term xConst = smtSolver.mkConst(intSort, "x");
  Term yConst = smtSolver.mkConst(intSort, "y");
  Term formula = smtSolver.mkTerm(LT, {xConst, yConst});

  smtSolver.assertFormula(formula);
  Result smtResult = smtSolver.checkSat();
  std::cout << "smtResult: " << smtResult << std::endl;
  std::cout << smtSolver.getModel({}, {xConst, yConst}) << std::endl;

  Solver sygusSolver;
  sygusSolver.setOption("produce-models", "true");
  sygusSolver.setOption("sygus", "true");
  sygusSolver.setOption("incremental", "false");
  Term xVar = sygusSolver.mkVar(intSort, "x");
  Term yVar = sygusSolver.mkVar(intSort, "y");
  Term min = sygusSolver.synthFun("min", {xVar, yVar}, intSort);

  sygusSolver.addSygusConstraint(formula);

  SynthResult sygusResult = sygusSolver.checkSynth();
  std::cout << "sygusResult: " << sygusResult << std::endl;
  if (sygusResult.hasSolution())
  {
    std::vector<Term> terms = {min};
    printSynthSolutions(terms, sygusSolver.getSynthSolutions(terms));
  }
}
```

We have about 450 options. There are functions that branch on their
string names. Previously, this was done with an if-else chain:

    if (name == "OPTION_1") { return ... }
    if (name == "OPTION_2") { return ... }
    ...

Now, we use a hashmap to enums, followed by a switch-case (jump table):

    OptionEnum t = MAP.at(name);
    switch (t) {
      case OPTION_1: return ...
      case OPTION_2: return ...
      ...
    }

This change seems to reduce the runtime of `get` by about 5x: the unit test that I added previously ran in ~1.23s and now it runs in ~0.24s.
